  if(swipeHorizontal){if(action==MotionEvent.ACTION_MOVE){float dx=e.getRawX()-swipeX;int target=UiRules.dragTarget(tab,dx);float span=pageSpan();positionPages(target<0?dx*.18f:Math.max(-span,Math.min(span,dx)),target);}
   else if(action==MotionEvent.ACTION_UP||action==MotionEvent.ACTION_CANCEL){float dx=e.getRawX()-swipeX;int target=incoming;boolean commit=action==MotionEvent.ACTION_UP&&swipeEligible&&target>=0&&UiRules.commitDrag(dx,pageSpan(),e.getEventTime()-swipeAt);swipeHorizontal=false;swipeEligible=false;animatePage(target,commit);}return true;}
  return super.dispatchTouchEvent(e);
