 void updateCells(JSONObject j){if(cellDelta==null)return;cellDelta.setText("压差 "+f(j,"delta",3)+" V");cellDelta.setTextColor(deltaColor(j.optDouble("delta",Double.NaN)));JSONArray a=j.optJSONArray("cells");int count=a==null?0:a.length();if(cellTitle!=null)cellTitle.setText("电芯电压"+(count>0?" · "+count+" 串":""));double lo=Double.POSITIVE_INFINITY,hi=Double.NEGATIVE_INFINITY;boolean all=count>0;for(int i=0;i<count&&all;i++){double n=a.optDouble(i,Double.NaN);if(!Double.isFinite(n)){all=false;break;}lo=Math.min(lo,n);hi=Math.max(hi,n);}for(int i=0;i<cellValues.length;i++){boolean show=i<count;View tile=cellTiles[i];if(tile!=null)tile.setVisibility(show?View.VISIBLE:View.GONE);TextView v=cellValues[i];if(v!=null){double n=show&&all?a.optDouble(i):Double.NaN;v.setText(UiRules.formatNumber(n,3)+" V");v.setTextColor(show&&all&&hi>lo?(n==hi?RED:n==lo?TEAL:FG):FG);}}for(int r=0;r<cellRows.length;r++){LinearLayout row=cellRows[r];if(row!=null){boolean visible=false;for(int k=0;k<4;k++){int i=r*4+k;if(i<count){visible=true;break;}}row.setVisibility(visible?View.VISIBLE:View.GONE);}}
 }
 void tiles(String[] labels,int start,int cols){LinearLayout row=new LinearLayout(this);for(int i=0;i<labels.length;i++){LinearLayout t=card();t.setPadding(dp(8),dp(10),dp(7),dp(10));TextView name=label(labels[i],11,MUT,false);if(values==overviewValues&&start+i==1)powerTitle=name;if(values==gpsValues&&start+i==3)rangeTitle=name;name.setSingleLine(true);name.setAutoSizeTextTypeUniformWithConfiguration(8,11,1,android.util.TypedValue.COMPLEX_UNIT_SP);t.addView(name,new LinearLayout.LayoutParams(-1,dp(18)));gap(t,6);TextView value=label("—",18,FG,true);value.setSingleLine(true);value.setAutoSizeTextTypeUniformWithConfiguration(10,19,1,android.util.TypedValue.COMPLEX_UNIT_SP);t.addView(value,new LinearLayout.LayoutParams(-1,dp(27)));values[start+i]=value;LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);if(i>0)p.leftMargin=dp(7);row.addView(t,p);}for(int i=labels.length;i<cols;i++){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,1,1);p.leftMargin=dp(7);row.addView(new View(this),p);}LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(9);body.addView(row,p);}
