 int deltaColor(double v){return !Double.isFinite(v)?MUT:UiRules.deltaWarning(v)?RED:TEAL;}
 void val(int i,String text,int color){if(values[i]!=null){values[i].setText(text);values[i].setTextColor(color);}}
 void stateBadge(TextView t,String text,boolean good){t.setText(text);t.setTextColor(good?TEAL:MUT);t.setBackground(bg(good?0xff263723:BORDER));}
 void updateOverview(JSONObject j){values=overviewValues;boolean valid=j.optBoolean("bmsValid");stateBadge(linkBadge,valid?"已连接":"无有效数据",valid);ring.soc=j.optDouble("soc",Double.NaN);ring.invalidate();capacity.setText(f(j,"ah",1)+" Ah");socBar.setProgress(Double.isFinite(ring.soc)?(int)Math.round(Math.max(0,Math.min(100,ring.soc))*10):0);String address=service.ble.g!=null?service.ble.g.getDevice().getAddress():"—";source.setText("来源："+address);JSONArray cells=j.optJSONArray("cells");int cellCount=cells==null?0:cells.length();deviceTitle.setText("保锂安 BMS"+(cellCount>0?" · "+cellCount+" 串":""));val(2,f(j,"voltage",2)+" V",FG);val(0,f(j,"current",2)+" A",AMBER);double power=j.optDouble("power",Double.NaN);powerTitle.setText(UiRules.powerTitle(power));val(1,UiRules.formatNumber(UiRules.powerMagnitude(power),0)+" W",AMBER);val(3,f(j,"delta",3)+" V",deltaColor(j.optDouble("delta",Double.NaN)));JSONArray a=j.optJSONArray("temps");double[] temps=new double[3];for(int i=0;i<3;i++)temps[i]=a==null?Double.NaN:a.optDouble(i,Double.NaN);for(int i=0;i<3;i++){int rank=UiRules.temperatureRank(temps,i);val(4+i,UiRules.formatNumber(temps[i],1)+" °C",rank>0?RED:rank<0?TEAL:FG);}flagsView.setText(flags(j));updateCells(j);}
 void updateGps(JSONObject j){values=gpsValues;boolean valid=j.optBoolean("gpsValid");stateBadge(gpsBadge,!service.gps?"未开启":valid?"定位正常":"等待定位",valid);speedValue.setText(f(j,"speed",1));val(0,f(j,"km",2)+" km",FG);val(1,f(j,"maxSpeed",0)+" km/h",BLUE);val(2,f(j,"eff",1)+" Wh/km",FG);boolean retained=Double.isFinite(j.optDouble("range",Double.NaN))&&!j.optBoolean("rangeCurrent");rangeTitle.setText(retained?"续航(上次估算)":"预计续航(估算)");val(3,f(j,"range",0)+" km",retained?AMBER:TEAL);val(4,f(j,"accuracy",0)+" m",FG);trend.samples=service.history.copy();trend.invalidate();}
 String flags(JSONObject j){int x=j.optInt("mosFlags",-1);if(x<0)return "MOS 状态：未知";return "充电MOS "+((x&64)!=0?"开":"关")+" / 放电MOS "+((x&128)!=0?"开":"关")+" / 预放电 "+((x&32)!=0?"开":"关")+"\n原始告警/保护/故障："+j.optString("alarm","—")+" / "+j.optString("protection","—")+" / "+j.optString("fault","—");}
 String f(JSONObject j,String key,int dec){double n=j.optDouble(key,Double.NaN);return UiRules.formatNumber(n,dec);}
 final Runnable refresh=new Runnable(){public void run(){if(service!=null){JSONObject j=service.snapshot();status.setText((j.optBoolean("bmsValid")?"● ":"○ ")+service.status);status.setTextColor(j.optBoolean("bmsValid")?TEAL:MUT);if(ring!=null)updateOverview(j);if(trend!=null)updateGps(j);updateDevices();}h.postDelayed(this,1000);}};
 class SocRing extends View {
  double soc=Double.NaN;final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);SocRing(Context c){super(c);}
  protected void onDraw(Canvas c){float cx=getWidth()/2f,cy=getHeight()/2f,r=Math.max(1,Math.min(cx,cy)-dp(7));RectF box=new RectF(cx-r,cy-r,cx+r,cy+r);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(8));p.setStrokeCap(Paint.Cap.ROUND);p.setColor(BORDER);c.drawCircle(cx,cy,r,p);if(Double.isFinite(soc)){p.setColor(TEAL);c.drawArc(box,-90,(float)(360*Math.max(0,Math.min(100,soc))/100),false,p);}p.setStyle(Paint.Style.FILL);p.setTextAlign(Paint.Align.CENTER);p.setTypeface(Typeface.create("sans-serif",Typeface.BOLD));p.setTextSize(Math.min(dp(29),r*.56f));p.setColor(FG);c.drawText(Double.isFinite(soc)?String.format(Locale.US,"%.1f",soc):"—",cx,cy+dp(3),p);p.setTypeface(Typeface.DEFAULT);p.setTextSize(dp(12));p.setColor(MUT);c.drawText("%",cx,cy+dp(22),p);}
 }
 class Trend extends View {
  List<TripHistory.Sample> samples=Collections.emptyList();final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);long selected=-1;float downX,downY;Trend(Context c){super(c);setContentDescription("最近60分钟行驶速度和平均耗电曲线，点击查看数值");}
  float left(){return dp(30);}float right(){return getWidth()-dp(30);}float top(){return dp(23);}float bottom(){return getHeight()-dp(25);}
  long end(){return SystemClock.elapsedRealtime();}long start(){return end()-TripHistory.WINDOW_MS;}
  float x(long at){return left()+(right()-left())*(at-start())/TripHistory.WINDOW_MS;}
  double scale(boolean speed){double max=1;for(TripHistory.Sample s:samples){double n=speed?s.speed:s.efficiency;if(Double.isFinite(n))max=Math.max(max,n);}return (speed?(max<=45?45:Math.max(60,Math.ceil(max/10)*10)):Math.max(10,Math.ceil(max/10)*10));}
  float y(double v,double max){return bottom()-(bottom()-top())*(float)Math.max(0,Math.min(1,v/max));}
  void text(Canvas c,String t,float x,float y,int color,Paint.Align align){p.setColor(color);p.setStyle(Paint.Style.FILL);p.setTextAlign(align);p.setTextSize(dp(10));c.drawText(t,x,y,p);}
  void line(Canvas c,boolean speed,double max,int color){p.setColor(color);p.setStrokeWidth(dp(1));p.setStyle(Paint.Style.STROKE);p.setStrokeCap(Paint.Cap.ROUND);Path path=new Path();TripHistory.Sample prev=null;for(TripHistory.Sample s:samples){double v=speed?s.speed:s.efficiency;if(!Double.isFinite(v)){prev=null;continue;}float xx=x(s.at),yy=y(v,max);if(prev!=null&&s.at-prev.at<=3000)path.lineTo(xx,yy);else{path.moveTo(xx,yy);c.drawPoint(xx,yy,p);}prev=s;}c.drawPath(path,p);p.setStyle(Paint.Style.FILL);}
  protected void onDraw(Canvas c){double sm=scale(true),em=scale(false);ArrayList<Double> ticks=new ArrayList<>();for(double v:new double[]{0,15,25,35,45})ticks.add(v);if(sm>45)ticks.add(sm);for(double v:ticks){float yy=y(v,sm);p.setColor(BORDER);p.setStrokeWidth(dp(1));c.drawLine(left(),yy,right(),yy,p);text(c,String.format(Locale.US,"%.0f",v),left()-dp(4),yy+dp(3),BLUE,Paint.Align.RIGHT);}for(int i=0;i<=4;i++){double v=em*i/4;float yy=y(v,em);text(c,String.format(Locale.US,"%.1f",v).replaceAll("\\.0$",""),right()+dp(4),yy+dp(3),AMBER,Paint.Align.LEFT);}c.save();c.clipRect(left(),top(),right()+1,bottom()+1);line(c,true,sm,BLUE);line(c,false,em,AMBER);c.restore();text(c,"-60min",left(),getHeight()-dp(6),MUT,Paint.Align.LEFT);text(c,"-30min",(left()+right())/2,getHeight()-dp(6),MUT,Paint.Align.CENTER);text(c,"现在",right(),getHeight()-dp(6),MUT,Paint.Align.RIGHT);TripHistory.Sample hit=null;long diff=Long.MAX_VALUE;boolean any=false;for(TripHistory.Sample s:samples){if(Double.isFinite(s.speed)||Double.isFinite(s.efficiency))any=true;if(selected>=start()&&selected<=end()&&Math.abs(s.at-selected)<diff){diff=Math.abs(s.at-selected);hit=s;}}if(!any)text(c,"等待有效数据",getWidth()/2f,(top()+bottom())/2,MUT,Paint.Align.CENTER);if(hit!=null&&diff<=2000){float xx=x(hit.at);p.setColor(MUT);p.setStrokeWidth(dp(1));c.drawLine(xx,top(),xx,bottom(),p);String sp=Double.isFinite(hit.speed)?String.format(Locale.US,"%.1f",hit.speed):"—",ef=Double.isFinite(hit.efficiency)?String.format(Locale.US,"%.1f",hit.efficiency):"—";text(c,sp+" km/h  /  "+ef+" Wh/km",getWidth()/2f,dp(15),FG,Paint.Align.CENTER);}}
  void select(float xx){float fraction=Math.max(0,Math.min(1,(xx-left())/Math.max(1,right()-left())));selected=start()+(long)(fraction*TripHistory.WINDOW_MS);invalidate();}
  public boolean onTouchEvent(android.view.MotionEvent e){switch(e.getActionMasked()){case MotionEvent.ACTION_DOWN:downX=e.getX();downY=e.getY();select(downX);return true;case MotionEvent.ACTION_MOVE:if(Math.abs(e.getX()-downX)>Math.abs(e.getY()-downY)&&Math.abs(e.getX()-downX)>dp(5))getParent().requestDisallowInterceptTouchEvent(true);select(e.getX());return true;case MotionEvent.ACTION_UP:select(e.getX());getParent().requestDisallowInterceptTouchEvent(false);performClick();return true;case MotionEvent.ACTION_CANCEL:getParent().requestDisallowInterceptTouchEvent(false);return true;}return super.onTouchEvent(e);}
  public boolean performClick(){super.performClick();return true;}
 }
